import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"人工智能安全","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/人工智能安全.md","filePath":"安全方向/人工智能安全.md","lastUpdated":1792430298000}'),i={name:"安全方向/人工智能安全.md"};function o(d,t,h,n,s,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="人工智能安全" tabindex="-1">人工智能安全 <a class="header-anchor" href="#人工智能安全" aria-label="Permalink to &quot;人工智能安全&quot;">​</a></h1><blockquote><p>前沿交叉方向。校内相关课程为「人工智能及安全」（方向课）。AI 既是被攻击的对象（对抗样本、模型窃取），也是安全的武器（智能检测、自动化攻防）。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>AI 已深度嵌入安全检测（恶意代码检测、入侵检测、内容安全）——学院在机器学习与安全结合方向有师资积累；</li><li>大模型时代，提示注入、模型安全、数据投毒成为新威胁维度；</li><li>这是一个快速扩张的蓝海方向，交叉背景（安全 + AI）稀缺且抢手。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./../专业基础/程序设计基础.html">程序设计基础</a>（Python）</li><li>机器学习基础概念（建议配合数学基础中的概率论）</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>AI 用于安全：恶意样本检测、异常检测、日志分析、NLP 内容安全</li><li>安全对抗 AI：对抗样本、数据投毒、模型窃取/反演</li><li>大模型安全：提示注入、越狱、幻觉风险、AI 内容滥用治理</li><li>自动化：AI 辅助漏洞挖掘、代码审计、智能渗透</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>校内《人工智能及安全》课程</td><td>课程</td><td>以课程主线为准</td></tr><tr><td><a href="https://owasp.org/www-project-top-10-for-large-language-model-applications/" target="_blank" rel="noreferrer">OWASP Top 10 for LLM Applications</a></td><td>文档</td><td>大模型应用安全权威清单</td></tr><tr><td>《人工智能安全》（相关专著）</td><td>拓展</td><td>中文系统读物</td></tr><tr><td>机器学习基础公开课（如 CS229/李宏毅）</td><td>公开课</td><td>补齐 AI 基础</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>先把 Python + 机器学习基础补齐，再谈 AI 安全；</li><li>关注学院「机器学习与安全」方向的科研项目，尽早进组；</li><li>大模型安全方向建议跟紧 OWASP LLM Top 10 等权威清单的动态更新。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>人工智能及安全（方向课）</li><li>数据挖掘 / 机器学习相关选修（以教务为准）</li></ul>',14)])])}const p=a(i,[["render",o]]);export{_ as __pageData,p as default};
